import json, pathlib, subprocess
root = pathlib.Path.cwd()
out = root / '.temp/review-r3'
out.mkdir(parents=True, exist_ok=True)
source = root / 'internal/contextpkg/skill_directory_vectors_test.go'
for path in ['internal/contextpkg/skill_directory_vectors_test.go', 'internal/contextpkg/testdata/profile-skill-directories-v1/fixtures.json', 'internal/contextlock/contextlock.go']:
    assert (root / path).read_bytes() == subprocess.check_output(['git', 'show', 'd29170ea6bcef3309d81b7f79b9c856e3e596965:' + path]), path
extra = '// Schema-4 carrier discriminants must be JSON numbers, including through disk Read.\nfunc TestReviewSkillDirectoryNumericDiscriminants(t *testing.T) {\n b,e:=os.ReadFile("testdata/profile-skill-directories-v1/fixtures.json"); if e!=nil {t.Fatal(e)}\n var fixture struct { Lock map[string]any `json:"candidate_lock"` }; if e=json.Unmarshal(b,&fixture);e!=nil{t.Fatal(e)}\n for _,field:=range []string{"schema_version","hash_version"} {t.Run(field,func(t *testing.T){\n  for _,invalid:=range []bool{false,true} {\n   v:=float64(4); if field=="hash_version" {v=2}; fixture.Lock[field]=v\n   if invalid {if field=="schema_version" {fixture.Lock[field]="4"} else {fixture.Lock[field]="2"}}\n   payload,e:=json.Marshal(fixture.Lock);if e!=nil{t.Fatal(e)}\n   f,e:=os.CreateTemp(t.TempDir(),"lock-*.json");if e!=nil{t.Fatal(e)};if _,e=f.Write(payload);e!=nil{t.Fatal(e)};f.Close()\n   _,_,e=contextlock.Read(f.Name())\n   if invalid && e==nil {t.Errorf("schema-4 Read admitted string %s; exact numeric discriminator required",field)}\n   if !invalid && e!=nil {t.Fatalf("numeric positive control refused: %v",e)}\n   fixture.Lock[field]=v\n  }\n })}\n}\n\n// Numeric member weights cannot be admitted from JSON strings.\nfunc TestReviewSkillDirectoryStringWeight(t *testing.T) {\n b,e:=os.ReadFile("testdata/profile-skill-directories-v1/fixtures.json");if e!=nil{t.Fatal(e)}\n var f struct{ Lock map[string]any `json:"candidate_lock"` };if e=json.Unmarshal(b,&f);e!=nil{t.Fatal(e)}\n member:=f.Lock["members"].([]any)[0].(map[string]any)\n for _,v:=range []any{float64(0),"0"} {\n member["weight"]=v;b,e=json.Marshal(f.Lock);if e!=nil{t.Fatal(e)}\n file,e:=os.CreateTemp(t.TempDir(),"lock-*.json");if e!=nil{t.Fatal(e)};file.Write(b);file.Close()\n _,_,e=contextlock.Read(file.Name())\n if _,bad:=v.(string);bad && e==nil{t.Error("schema-4 Read admitted string weight")}else if !bad && e!=nil{t.Fatalf("numeric control refused: %v",e)}\n }\n}\n'
replacement = out / 'numeric-probe_test.go'
replacement.write_text(source.read_text() + '\n' + extra)
(out / 'numeric-overlay.json').write_text(json.dumps({'Replace': {str(source): str(replacement)}}))
print('Created test-only overlay for exact revision 3; production files unchanged.')
